-- 85 Guest Book: three text fields written straight onto the page. Click a
-- line to write on it; Enter moves down and, on the last, signs the book.
-- The new entry inks in on the left and is saved. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/85-guest-book.scene"
local SLOT = "guest_book"
local SEED = {
    { name = "Bram the Tinker", from = "Low Ford", word = "The stew was worth the rain." },
    { name = "Åsa Lindqvist", from = "Göteborg", word = "Warm beds, and a cat who keeps the hearth." },
    { name = "Zoë Kowalczyk", from = "Kraków", word = "Sang until the candles ran out. Will return." },
    { name = "Old Hesketh", from = "the Fells", word = "Ale's better than last year. Tell nobody." },
}
local FIELDS = { "GbName", "GbFrom", "GbWord" }
local INK = { 0.0153, 0.0085, 0.006 }
local SAID = { 0.0835, 0.047, 0.0331 }
local captions = true
local entries = {}
local who, said = {}, {}
local fields = {}
local sign, note
local fresh = 0      -- seconds the newest entry has been drying
local was_pressed = false
local note_t = 0

local function show()
    for k = 1, #who do
        local e = entries[k]
        Text.set(who[k], e and (e.name .. ",  of " .. e.from) or "")
        Text.set(said[k], e and ("\"" .. e.word .. "\"") or "")
        -- The newest entry inks in.
        local a = (k == 1 and fresh < 1.5) and (fresh / 1.5) or 1
        Text.set_color(who[k], INK[1], INK[2], INK[3], a)
        Text.set_color(said[k], SAID[1], SAID[2], SAID[3], a)
    end
end

local function focus(i)
    for j, f in ipairs(fields) do UI.set_prop(f, "focused", j == i) end
end

local function sign_book()
    local name = UI.get_prop(fields[1], "text") or ""
    local from = UI.get_prop(fields[2], "text") or ""
    local word = UI.get_prop(fields[3], "text") or ""
    if name:match("^%s*$") then
        Text.set(note, "The book wants a name first.")
        note_t = 2.5
        focus(1)
        return
    end
    if from:match("^%s*$") then from = "parts unknown" end
    if word:match("^%s*$") then word = "..." end
    table.insert(entries, 1, { name = name, from = from, word = word })
    while #entries > 12 do table.remove(entries) end
    Save.set(SLOT, "entries", entries)
    Save.commit(SLOT)
    for _, f in ipairs(fields) do UI.set_prop(f, "text", "") end
    focus(1)
    fresh = 0
    Text.set(note, "Signed. Welcome, " .. name .. ".")
    note_t = 3.0
end

function init(entity)
    for k = 0, 4 do
        who[k + 1] = Entity.find_by_name("Entry" .. k .. "Who")
        said[k + 1] = Entity.find_by_name("Entry" .. k .. "Said")
    end
    for i, n in ipairs(FIELDS) do fields[i] = Entity.find_by_name(n) end
    sign = Entity.find_by_name("GbSign")
    note = Entity.find_by_name("GbNote")
    local saved = Save.get(SLOT, "entries")
    if type(saved) == "table" and #saved > 0 then entries = saved else entries = SEED end
    fresh = 99
    focus(1)
    Cursor.set_image("sprites/options/quill.png", 2, 30)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    fresh = fresh + dt
    -- Enter in a field: on to the next, or sign from the last.
    for i, f in ipairs(fields) do
        if UI.get_prop(f, "submitted") then
            if i < #fields then focus(i + 1) else sign_book() end
        end
    end
    local pressed = UI.get_prop(sign, "pressed") and true or false
    if was_pressed and not pressed and UI.get_prop(sign, "hovered") then sign_book() end
    was_pressed = pressed
    if note_t > 0 then
        note_t = note_t - dt
        if note_t <= 0 then Text.set(note, "") end
    end
    show()
end
